module TopModule (
    input  logic        clk,
    input  logic        load,
    input  logic [511:0] data,
    output logic [511:0] q
);

    logic [511:0] next_q;

    always_comb begin
        for (int i = 0; i < 512; i++) begin
            logic l, c, r;
            l = (i == 511) ? 1'b0 : q[i+1];
            c = q[i];
            r = (i == 0)   ? 1'b0 : q[i-1];

            // Rule 110 table:
            // 111 -> 0
            // 110 -> 1
            // 101 -> 1
            // 100 -> 0
            // 011 -> 1
            // 010 -> 1
            // 001 -> 1
            // 000 -> 0
            // Formula: (~l & c) | (~c & r) | (l & c & ~r)
            next_q[i] = (~l & c) | (~c & r) | (l & c & ~r);
        end
    end

    always_ff @(posedge clk) begin
        if (load) begin
            q <= data;
        end else begin
            q <= next_q;
        end
    end

endmodule

